let preference=localStorage.getItem('bean-language')||'zh-CN';
const system=()=>window.BeanAndroid?.systemLanguage?.()||navigator.language;
export const isEnglish=()=>preference==='system'&&/^en/i.test(system());
export const getLanguage=()=>preference;
const originals=new WeakMap();
export function translateText(text){if(!isEnglish())return text;const trimmed=text.trim();if(dictionary[trimmed])return text.replace(trimmed,dictionary[trimmed]);return text.replace(/登记 (?=\d)/g,'Registered ').replace(/拟购 (?=¥|￥)/g,'Planned ').replace(/实际 (?=¥|￥)/g,'Actual ').replace(/已购买/g,'Purchased').replace(/待购买/g,'To buy').replace(/本月收入/g,'Monthly income').replace(/本年收入/g,'Yearly income').replace(/总收入/g,'Total income').replace(/固定总预算/g,'Fixed total budget');}
export function applyLanguage(){
 document.documentElement.lang=isEnglish()?'en':'zh-CN';document.title=location.pathname.endsWith('/browser.html')?(isEnglish()?'Bean Workbench · Browser':'不务正豆·浏览器兼容版'):(isEnglish()?'Bean Workbench':'不务正豆工作台');
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement?.closest('script,style,[data-user-text]')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});let node;
 while((node=walker.nextNode())){const old=originals.get(node),source=old&&node.nodeValue===old.translated?old.source:node.nodeValue;const translated=translateText(source);if(translated!==node.nodeValue)node.nodeValue=translated;originals.set(node,{source,translated});}
}
export function setLanguage(value){if(!['system','zh-CN'].includes(value))return;preference=value;localStorage.setItem('bean-language',value);window.BeanAndroid?.setLanguage?.(value);applyLanguage();}
export function watchLanguage(){applyLanguage();let queued=false;const observer=new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{observer.disconnect();applyLanguage();observer.observe(document.body,{childList:true,subtree:true,characterData:true});queued=false;});});observer.observe(document.body,{childList:true,subtree:true,characterData:true});}
